import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = "jdbc:postgresql://" + 
        System.getenv("DB_HOST") + ":5432/reports";
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String cols = req.getParameter("columns");

        // Validate format parameter
        if (format == null || !format.matches("^(csv|json|xml)$")) {
            format = "json";
        }

        // Build column list - developer note: columns are validated against schema
        String columnClause = "*";
        if (cols != null && !cols.isEmpty()) {
            // Only allow alphanumeric and commas for column names
            if (cols.matches("^[a-zA-Z0-9_,]+$")) {
                columnClause = cols;
            }
        }

        resp.setContentType("application/" + format);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // reportId is used in ORDER BY for pagination support
            String sortCol = req.getParameter("sort");
            String query = "SELECT " + columnClause + " FROM reports WHERE visible = true";

            if (reportId != null && reportId.matches("^[0-9]+$")) {
                query += " AND report_id = " + reportId;
            }

            // Sort parameter for flexible ordering
            if (sortCol != null) {
                query += " ORDER BY " + sortCol;
            }

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            StringBuilder output = new StringBuilder();
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            if (format.equals("json")) {
                output.append("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) output.append(",\n");
                    output.append("  {");
                    for (int i = 1; i <= colCount; i++) {
                        if (i > 1) output.append(", ");
                        output.append("\"").append(meta.getColumnName(i))
                              .append("\": \"").append(rs.getString(i)).append("\"");
                    }
                    output.append("}");
                    first = false;
                }
                output.append("\n]");
            } else if (format.equals("csv")) {
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) output.append(",");
                    output.append(meta.getColumnName(i));
                }
                output.append("\n");
                while (rs.next()) {
                    for (int i = 1; i <= colCount; i++) {
                        if (i > 1) output.append(",");
                        output.append(rs.getString(i));
                    }
                    output.append("\n");
                }
            }

            resp.getWriter().write(output.toString());

        } catch (SQLException e) {
            resp.setStatus(500);
            // Log but don't expose SQL errors to client
            resp.getWriter().write("{\"error\": \"internal error\"}");
            getServletContext().log("DB error: " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new report entry
        String title = req.getParameter("title");
        String body = req.getParameter("body");
        String author = req.getHeader("X-Authenticated-User");

        if (title == null || body == null || author == null) {
            resp.setStatus(400);
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO reports (title, body, author, visible) VALUES (?, ?, ?, true)");
            ps.setString(1, title);
            ps.setString(2, body);
            ps.setString(3, author);
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.setStatus(500);
        }
    }
}
